function changeCount(c) {
    // Split the input string by comma and convert to floats (if possible)
    var values = c.split(',');
    var dollars = 0;
    for (var i = 0; i < values.length; i++) {
        var value = values[i];
        if (CHANGE.hasOwnProperty(value)) {
            dollars += CHANGE[value];
        }
    }
    // Return the total in the format $x.xx
    return `$${dollars.toFixed(2)}`;
}
